# Keep Development/testing permanently last in Settings.
settings_start=s.index('    <div id="view-settings" class="panelView">')
settings_end=s.index('    <div id="view-changelog" class="panelView">',settings_start)
settings=s[settings_start:settings_end]
dev_match=re.search(r'''\n      <details class="settingsGroup">\n        <summary><span>Development / testing</span>.*?\n      </details>''',settings,re.S)
if not dev_match:
    raise SystemExit('development settings group not found')
dev=dev_match.group(0)
settings=settings[:dev_match.start()]+settings[dev_match.end():]
last_close=settings.rfind('    </div>')
if last_close<0:
    raise SystemExit('settings closing div not found')
settings=settings[:last_close]+'''\n      <!-- Keep Development / testing as the final Settings category in future versions. -->'''+dev+'\n'+settings[last_close:]
s=s[:settings_start]+settings+s[settings_end:]

