pattern=r'''function updateTopRoleBadge\(\)\{.*?\n\}\nfunction updateGameDashboard\(\)\{.*?\n\}\n(?=function seekerPointsEarned)'''
replacement='''function updateTopRoleBadge(){\n  const badge=document.getElementById("roomTopStatus");if(!badge)return;\n  badge.classList.remove("connected","hider","seeker");\n  if(!roomModeConnected()){badge.textContent="OFFLINE";return;}\n  const role=roomRole(),code=window.BigWalkRooms?.getRoomCode?.()||"ROOM";\n  badge.textContent=`${role==="hider"?"HIDER":"SEEKER"} · ${code}`;\n  badge.classList.add("connected",role==="hider"?"hider":"seeker");\n}\nfunction hidingTimeRemaining(){return Math.max(0,Number(hidingSettings.duration||0)-currentMatchSeconds());}\nfunction updateRoomChrome(){\n  const connected=roomModeConnected(),isHider=connected&&roomRole()==="hider";\n  const actions=document.getElementById("topRoomActions"),popover=document.getElementById("roomConnected"),count=document.getElementById("roomPlayerCount"),playersBtn=document.getElementById("roomPlayersBtn"),qTab=document.querySelector('.tabBtn[data-tab="questions"]');\n  if(actions)actions.style.display=connected?"flex":"none";\n  if(count)count.textContent=String(document.getElementById("roomMemberList")?.children?.length||0);\n  if(!connected&&popover)popover.classList.remove("open");\n  if(playersBtn)playersBtn.setAttribute("aria-expanded",String(!!popover?.classList.contains("open")));\n  if(qTab)qTab.style.display=isHider?"none":"";\n  if(isHider&&activeTab==="questions")showTab("game");\n}\nfunction updateGameDashboard(){\n  const card=document.getElementById("currentActionSection");if(!card)return;\n  const eyebrow=document.getElementById("currentActionEyebrow"),title=document.getElementById("currentActionTitle"),timer=document.getElementById("currentActionTimer"),detail=document.getElementById("currentActionDetail"),next=document.getElementById("currentActionNext"),secondary=document.getElementById("currentActionSecondary");\n  const controls=document.getElementById("matchControlSection"),points=document.getElementById("seekerPointsSection"),qSection=document.getElementById("questionNextSection"),qStatus=document.getElementById("gameQuestionStatus"),qNext=document.getElementById("gameQuestionNext"),relocationSection=document.getElementById("relocationGameSection");\n  const connected=roomModeConnected(),role=connected?roomRole():null,isHider=role==="hider",isSeeker=role==="seeker",sec=currentMatchSeconds(),running=connected?roomMatchRunning():matchRunning;\n  card.style.display=connected?"block":"none";\n  controls.style.display=connected&&!!window.BigWalkRooms?.isHost?.()?"block":"none";\n  if(relocationSection)relocationSection.style.display=connected?"block":"none";\n  points.style.display=isSeeker?"block":"none";qSection.style.display=isSeeker?"block":"none";\n  const hideRemaining=Math.max(0,Number(hidingSettings.duration||0)-sec);\n  if(isSeeker){\n    const anyUnlocked=testingUnlockOverride||Object.values(unlockTimes).some(t=>sec>=Number(t));\n    if(sec<.01&&!running){qStatus.textContent="Waiting";qNext.textContent=hidingSettings.firstQuestionOnEnd?"First question unlocks when hiding time ends.":`First question unlocks ${formatApproxDuration(unlockTimes.grid)} after the match starts.`;}\n    else if(hideRemaining>.01&&hidingSettings.firstQuestionOnEnd&&!testingUnlockOverride){qStatus.textContent="Locked · hiding time";qNext.textContent=`Centerline unlocks when hiding time ends (${formatApproxDuration(hideRemaining)}).`;}\n    else if(relocationState.active){qStatus.textContent="Locked";qNext.textContent="Questions are unavailable during forced relocation.";}\n    else if(questionCooldownActive()){qStatus.textContent=`Cooling down · ${formatApproxDuration(questionCooldownRemaining())}`;qNext.textContent=nextQuestionUnlockInfo(sec)+".";}\n    else{qStatus.textContent=anyUnlocked?"Ready":"Locked";qNext.textContent=nextQuestionUnlockInfo(sec)+".";}\n  }\n  card.classList.remove("hider","seeker","urgent");if(isHider)card.classList.add("hider");if(isSeeker)card.classList.add("seeker");\n  timer.style.display="none";eyebrow.textContent="CURRENT STATUS";\n  const relocationNext=Math.max(0,Number(relocationState.nextAt??relocationSettings.firstAt)-sec);\n  next.textContent=missionState.active?"Relocation · paused":`Next relocation · ${formatApproxDuration(relocationNext)}`;\n  secondary.textContent=isHider?`⚡ ${Math.max(0,Number(hiderPowerCharges||0))} Power Charge${Number(hiderPowerCharges||0)===1?"":"s"}`:isSeeker?`${seekerPointsBalance()} Seeker Point${seekerPointsBalance()===1?"":"s"}`:"—";\n  if(!connected)return;\n  if(sec<.01&&!running){title.textContent="Ready to play";detail.textContent=window.BigWalkRooms?.isHost?.()?"Start the match when everyone is ready.":"Waiting for the room host to start the match.";next.textContent="Match not started";return;}\n  if(!running){title.textContent="Match paused";detail.textContent="Gameplay timers are paused.";next.textContent="Waiting to resume";return;}\n  if(hideRemaining>.01){\n    eyebrow.textContent="HIDING PHASE";title.textContent=isHider?"Find your hiding spot":"Give the Hider time";timer.style.display="block";timer.textContent=formatTime(hideRemaining);\n    detail.textContent=isHider?"Get into position before hiding time ends.":"Searching begins when the hiding timer reaches zero.";\n    next.textContent=hidingSettings.firstQuestionOnEnd?"First question · at hide end":"First question · separate schedule";return;\n  }\n  if(relocationState.active){\n    card.classList.add("urgent");eyebrow.textContent="CURRENT OBJECTIVE";\n    const rem=Math.max(0,Number(relocationState.deadline||sec)-sec);timer.style.display="block";timer.textContent=rem>0?formatTime(rem):"OVERTIME";\n    title.textContent=isHider?"Forced relocation":"Hider relocating";\n    if(isHider&&localRelocationPlan&&!localRelocationPlan.invalid&&!localRelocationPlan.skip&&liveMarker){const d=Math.hypot(liveMarker.x-localRelocationPlan.start.x,liveMarker.y-localRelocationPlan.start.y);detail.textContent=`${Math.round(d)} / ${Math.round(localRelocationPlan.target)} units from relocation start.`;}\n    else detail.textContent=isHider?"Move to a legal new hiding area and press Ready when the target is met.":"Questions are locked until the Hider finishes relocating.";\n    next.textContent=rem>0?"Target window active":"Overtime penalty active";return;\n  }\n  if(missionState.active){\n    eyebrow.textContent="CURRENT OBJECTIVE";title.textContent=isHider?"Cross the Zone":"Hider mission active";\n    if(isHider&&liveMarker&&localHiderMissionPlan&&!localHiderMissionPlan.invalid){const d=missionDistanceToTarget(liveMarker,localHiderMissionPlan);detail.textContent=Number.isFinite(d)?`${Math.max(0,Math.round(d))} units to the purple target area.`:"Reach the private purple target area.";}\n    else detail.textContent=isHider?"Reach the private purple target area.":"The mission target and Hider progress remain private.";\n    next.textContent="Forced relocation · paused";return;\n  }\n  if(isHider&&missionState.available){eyebrow.textContent="OPTIONAL OBJECTIVE";title.textContent="Mission available";detail.textContent="Cross the Zone is ready whenever you want to take it.";return;}\n  title.textContent=isHider?"Stay hidden":"Search for the Hider";\n  detail.textContent=isHider?"No movement objective is active. Stay put unless you choose a mission.":questionCooldownActive()?"An unlocked question is cooling down.":"Use the map and spend points on available questions.";\n}\n'''
regex_once(pattern,replacement,'dashboard functions')

# Configurable price functions.
price_pattern=r'''function towerRadiusCost\(radius\)\{.*?\n\}\nfunction landmarkRadiusCost\(radius\)\{.*?\n\}\nfunction markerRadiusCost\(radius\)\{.*?\n\}\nfunction questionCostFor\(key\)\{.*?\n\}'''
price_repl='''function towerRadiusCost(radius){\n  radius=Number(radius);\n  if(radius>=500)return questionCosts.tower500;\n  if(radius>=400)return questionCosts.tower400;\n  if(radius>=300)return questionCosts.tower300;\n  return questionCosts.tower250;\n}\nfunction landmarkRadiusCost(radius){\n  radius=Number(radius);\n  if(radius>=500)return questionCosts.landmark500;\n  if(radius>=400)return questionCosts.landmark400;\n  if(radius>=300)return questionCosts.landmark300;\n  if(radius>=200)return questionCosts.landmark200;\n  return questionCosts.landmark150;\n}\nfunction markerRadiusCost(radius){\n  radius=Number(radius);\n  if(radius>=500)return questionCosts.marker500;\n  if(radius>=400)return questionCosts.marker400;\n  if(radius>=300)return questionCosts.marker300;\n  return questionCosts.marker250;\n}\nfunction questionCostFor(key){\n  if(key==="grid")return Number(questionCosts.grid||0);\n  if(key==="nearest")return Number(questionCosts.nearest||0);\n  if(key==="towerRadius")return towerRadiusCost(document.getElementById("radarRadius").value);\n  if(key==="landmark")return document.getElementById("landmarkQuestionType").value==="nearest"?Number(questionCosts.landmarkNearest||0):landmarkRadiusCost(document.getElementById("landmarkRadius").value);\n  if(key==="marker")return document.getElementById("markerQuestionType").value==="direction"?Number(questionCosts.markerDirection||0):markerRadiusCost(document.getElementById("markerRadius").value);\n  return 0;\n}'''
regex_once(price_pattern,price_repl,'price functions')

