once('''function updateRuleTimes(){\n  document.getElementById("ruleGridTime").textContent=formatTime(unlockTimes.grid);''','''function updateRuleTimes(){\n  document.getElementById("ruleHideTime").textContent=formatTime(hidingSettings.duration);\n  document.getElementById("ruleGridTime").textContent=formatTime(unlockTimes.grid);''','rule timer update')

schedule_pattern=r'''function updateScheduleInputs\(\)\{.*?\n\}\n(?=function renderMatchTimer)'''
schedule_repl='''function syncHideTimeControls(){\n  const hide=document.getElementById("hideTimeMinutes"),linked=document.getElementById("firstQuestionOnHideEnd"),first=document.getElementById("firstUnlockMinutes"),grid=document.getElementById("gridUnlockMinutes");\n  if(!hide||!linked||!first||!grid)return;\n  first.disabled=!!linked.checked;grid.disabled=!!linked.checked;\n  if(linked.checked){first.value=hide.value;grid.value=hide.value;}\n}\nfunction updateScheduleInputs(){\n  document.getElementById("hideTimeMinutes").value=hidingSettings.duration/60;\n  document.getElementById("firstQuestionOnHideEnd").checked=hidingSettings.firstQuestionOnEnd!==false;\n  document.getElementById("firstUnlockMinutes").value=unlockTimes.grid/60;\n  document.getElementById("gridUnlockMinutes").value=unlockTimes.grid/60;\n  document.getElementById("nearestUnlockMinutes").value=unlockTimes.nearest/60;\n  document.getElementById("towerRadiusUnlockMinutes").value=unlockTimes.towerRadius/60;\n  document.getElementById("landmarkUnlockMinutes").value=unlockTimes.landmark/60;\n  document.getElementById("markerUnlockMinutes").value=unlockTimes.marker/60;\n  document.getElementById("questionCooldownMinutes").value=questionCooldownSeconds/60;\n  syncHideTimeControls();\n  document.getElementById("scheduleSummary").textContent=`Hiding: ${formatTime(hidingSettings.duration)} · Unlocks: ${formatTime(unlockTimes.grid)} → ${formatTime(unlockTimes.nearest)} → ${formatTime(unlockTimes.towerRadius)} → ${formatTime(unlockTimes.landmark)} → ${formatTime(unlockTimes.marker)} · Cooldown: ${formatTime(questionCooldownSeconds)}`;\n}\nfunction updateQuestionCostInputs(){\n  const ids={costGrid:"grid",costNearest:"nearest",costLandmarkNearest:"landmarkNearest",costMarkerDirection:"markerDirection",costTower500:"tower500",costTower400:"tower400",costTower300:"tower300",costTower250:"tower250",costLandmark500:"landmark500",costLandmark400:"landmark400",costLandmark300:"landmark300",costLandmark200:"landmark200",costLandmark150:"landmark150",costMarker500:"marker500",costMarker400:"marker400",costMarker300:"marker300",costMarker250:"marker250"};\n  for(const [id,key] of Object.entries(ids)){const el=document.getElementById(id);if(el)el.value=String(questionCosts[key]);}\n}\n'''
regex_once(schedule_pattern,schedule_repl,'schedule input functions')

