# Replace schedule builder + apply block and add prices handler.
handlers_pattern=r'''document\.getElementById\("buildScheduleBtn"\)\.onclick=\(\)=>\{.*?\n\};\ndocument\.getElementById\("applyScheduleBtn"\)\.onclick=\(\)=>\{.*?\n\};\n(?=document\.getElementById\("testUnlockOverride"\))'''
handlers_repl='''document.getElementById("hideTimeMinutes").addEventListener("input",syncHideTimeControls);\ndocument.getElementById("firstQuestionOnHideEnd").addEventListener("change",syncHideTimeControls);\ndocument.getElementById("buildScheduleBtn").onclick=()=>{\n  const linked=document.getElementById("firstQuestionOnHideEnd").checked;\n  const hide=+document.getElementById("hideTimeMinutes").value;\n  const requestedFirst=+document.getElementById("firstUnlockMinutes").value;\n  const first=linked?hide:requestedFirst;\n  const interval=+document.getElementById("unlockIntervalMinutes").value;\n  const v=document.getElementById("scheduleValidation");v.textContent="";\n  if(!Number.isFinite(hide)||hide<0||!Number.isFinite(first)||first<0||!Number.isFinite(interval)||interval<=0){v.textContent="Use a hiding time / first unlock of 0 minutes or more and an interval greater than 0.";return;}\n  const vals=[first,first+interval,first+2*interval,first+3*interval,first+4*interval];\n  ["gridUnlockMinutes","nearestUnlockMinutes","towerRadiusUnlockMinutes","landmarkUnlockMinutes","markerUnlockMinutes"].forEach((id,i)=>document.getElementById(id).value=vals[i]);\n  document.getElementById("scheduleSummary").textContent=`Preview: hiding ${formatTime(hide*60)} · questions ${vals.map(m=>formatTime(m*60)).join(" → ")}`;\n};\ndocument.getElementById("applyScheduleBtn").onclick=()=>{\n  if(!roomCanEditSharedGame()){document.getElementById("scheduleValidation").textContent="Shared room: only seekers (or the host) can change match timing.";return;}\n  const linked=document.getElementById("firstQuestionOnHideEnd").checked;\n  const hideMinutes=+document.getElementById("hideTimeMinutes").value;\n  const ids=["gridUnlockMinutes","nearestUnlockMinutes","towerRadiusUnlockMinutes","landmarkUnlockMinutes","markerUnlockMinutes"];\n  const vals=ids.map(id=>+document.getElementById(id).value);\n  if(linked)vals[0]=hideMinutes;\n  const cooldownMinutes=+document.getElementById("questionCooldownMinutes").value;\n  const v=document.getElementById("scheduleValidation");v.textContent="";\n  if(!Number.isFinite(hideMinutes)||hideMinutes<0){v.textContent="Hiding time must be 0 minutes or greater.";return;}\n  if(vals.some(x=>!Number.isFinite(x)||x<0)){v.textContent="Unlock times must be 0 minutes or greater.";return;}\n  if(!(vals[0]<=vals[1]&&vals[1]<=vals[2]&&vals[2]<=vals[3]&&vals[3]<=vals[4])){v.textContent="Unlock times must stay in order: Centerline ≤ Nearest Tower ≤ Tower Radius ≤ Landmark Questions ≤ Marker Questions.";return;}\n  if(!Number.isFinite(cooldownMinutes)||cooldownMinutes<=0){v.textContent="Question cooldown must be greater than 0 minutes.";return;}\n  hidingSettings={duration:hideMinutes*60,firstQuestionOnEnd:linked};\n  unlockTimes={grid:vals[0]*60,nearest:vals[1]*60,towerRadius:vals[2]*60,landmark:vals[3]*60,marker:vals[4]*60};\n  questionCooldownSeconds=cooldownMinutes*60;\n  updateScheduleInputs();renderMatchTimer();notifyRoomGameStateChanged();\n  v.style.color="#9ef1c2";v.textContent="Timing settings applied.";setTimeout(()=>{v.textContent="";v.style.color="";},1500);\n};\ndocument.getElementById("applyQuestionCostsBtn").onclick=()=>{\n  const v=document.getElementById("questionCostsValidation");v.textContent="";\n  if(roomModeConnected()&&!window.BigWalkRooms?.isHost?.()){v.textContent="Only the room host can change question prices.";return;}\n  const ids={costGrid:"grid",costNearest:"nearest",costLandmarkNearest:"landmarkNearest",costMarkerDirection:"markerDirection",costTower500:"tower500",costTower400:"tower400",costTower300:"tower300",costTower250:"tower250",costLandmark500:"landmark500",costLandmark400:"landmark400",costLandmark300:"landmark300",costLandmark200:"landmark200",costLandmark150:"landmark150",costMarker500:"marker500",costMarker400:"marker400",costMarker300:"marker300",costMarker250:"marker250"};\n  const nextCosts={};\n  for(const [id,key] of Object.entries(ids)){const value=+document.getElementById(id).value;if(!Number.isFinite(value)||value<0||!Number.isInteger(value)){v.textContent="Question prices must be whole numbers of 0 points or more.";return;}nextCosts[key]=value;}\n  questionCosts=nextCosts;updateQuestionCostInputs();updateQuestionEconomy();notifyRoomGameStateChanged();\n  v.style.color="#9ef1c2";v.textContent="Question prices applied.";setTimeout(()=>{v.textContent="";v.style.color="";},1500);\n};\n'''
regex_once(handlers_pattern,handlers_repl,'schedule + price handlers')

